((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null, points: row.points ?? meta.points,
      ...(Number.isInteger(numericAnswer) ? {numericAnswer, questionNote: 'В тренировочном рейтинге за эту задачу баллы не начисляются.'} : {}),
      ...(audio ? {audio: folder + 'listening.mp3'} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  return {
    id: year + '-' + subject + '-' + grade, year, grades, label: grades.join('–') + ' классы',
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2026,"grade":"3-4","contest":"Золотое руно","letters":"ABCD","count":30,"language":"ru","points":1,"tasksFile":"tasks.pdf","answersFile":"answers.pdf"}, [{"title":"Новогодняя столица","question":"Этот город встретил 1 января 2026 года в статусе Новогодней столицы России.","choices":["Рязань","Киров","Суздаль","Владимир"],"answer":0,"steps":["У проекта «Новогодняя столица России» каждый год новый город. Ищем программу на зиму 2025–2026 годов, потому что в условии указано 1 января 2026 года.","Зимние мероприятия проекта 2026 года принимала Рязань. Она передала символ проекта Вологде только 7 января, поэтому 1 января статус ещё принадлежал Рязани."]},{"title":"Имя святого апостола","question":"Единственный город в России, названный в честь святого апостола — ....","choices":["Архангельск","Екатеринбург","Санкт-Петербург","Ставрополь"],"answer":2,"steps":["В названии Санкт-Петербург слово «санкт» означает «святой». Проверим, кто такой Пётр в названии города.","Санкт-Петербург получил имя апостола Петра. Архангельск назван в честь архангела Михаила, в имени Екатеринбурга звучит имя святой Екатерины, а Ставрополь означает «город креста»."]},{"title":"Столица в летописи","question":"С этим князем связано первое упоминание современной столицы Российской Федерации в летописях.","choices":["Вещий Олег","Юрий Долгорукий","Ярослав Мудрый","Владимир Мономах"],"answer":1,"steps":["Современная столица России — Москва. Её первое известное летописное упоминание относится к 1147 году.","В записи о встрече в Москве названы Юрий Долгорукий и Святослав Ольгович. Из предложенных князей в этой записи назван Юрий Долгорукий."]},{"title":"Столица Заполярья","question":"Этот город считается столицей русского Заполярья.","choices":["Мурманск","Архангельск","Петрозаводск","Салехард"],"answer":0,"steps":["Заполярье находится за Северным полярным кругом. Мурманск расположен севернее него, а через Салехард проходит сам Полярный круг.","Сравним города по размеру. Мурманск — самый большой город мира за Северным полярным кругом. За ним и закрепилось название столицы русского Заполярья."]},{"title":"Сибирская крепость","question":"Этот областной центр возник из крепости, заложенной в 1586 году, и является старейшим из существующих русских городов в Сибири.","choices":["Омск","Новосибирск","Тюмень","Томск"],"answer":2,"steps":["Сравним даты основания. Томск основан в 1604 году, Омск — в 1716-м, а Новосибирск появился в конце XIX века.","В 1586 году русскую крепость заложили на реке Туре. Из неё выросла Тюмень, которая появилась раньше остальных городов в списке."]},{"title":"Памятник в море","question":"В этой черноморской столице установлен памятник затопленным кораблям.","choices":["Сочи","Евпатория","Туапсе","Севастополь"],"answer":3,"steps":["На фотографии колонна стоит на скале прямо в море. Памятник напоминает о кораблях, которые затопили во время Крымской войны, чтобы перекрыть вход в бухту.","Эта бухта называется Севастопольской. Памятник находится у Приморского бульвара в Севастополе."],"figure":{"src":"assets/golden-fleece/2026/06.webp","alt":"Высокая колонна с фигурой орла на скале посреди моря","width":443,"height":302}},{"title":"Дар императрицы","question":"Этот город возник благодаря дару императрицы черноморским казакам, что отразилось в его первом названии.","choices":["Новороссийск","Сочи","Черкесск","Краснодар"],"answer":3,"steps":["В 1792 году Екатерина II пожаловала черноморским казакам земли на Кубани. Своё поселение казаки назвали Екатеринодаром в честь императрицы.","В 1920 году Екатеринодар переименовали в Краснодар. В вариантах дано современное название города."]},{"title":"Нулевой километр","question":"В этом городе, считающемся столицей Золотого кольца России, установлен памятник нулевому километру туристического маршрута.","choices":["Тверь","Владимир","Кострома","Ярославль"],"answer":3,"steps":["Ищем памятник с указателями, от которого отсчитывают километры Золотого кольца. Такой знак открыли в 2013 году на улице Революционной.","Улица Революционная с этим памятником находится в Ярославле. Именно там отмечена условная точка начала маршрута."],"figure":{"src":"assets/golden-fleece/2026/08.webp","alt":"Столб с указателями и каменным основанием на аллее","width":323,"height":365}},{"title":"Центр Ленинградской области","question":"Столицей Ленинградской области в настоящее время является город ....","choices":["Санкт-Петербург","Ленинград","Гатчина","Великий Новгород"],"answer":2,"steps":["Ленинград — прежнее имя Санкт-Петербурга. Название области сохранилось после переименования города в 1991 году.","Сверим ответ с Уставом Ленинградской области. В нём столицей области указана Гатчина. Эта норма действует с 2023 года."]},{"title":"Высокая конная статуя","question":"Самая высокая конная статуя в России — памятник национальному герою республики — находится в главном городе ....","choices":["Башкортостана","Татарстана","Карелии","Чечни"],"answer":0,"steps":["Всадник на фотографии держит плеть над головой. На этом памятнике изображён Салават Юлаев. Высота самой статуи составляет 9,8 метра.","Памятник установлен в Уфе. Уфа — главный город Башкортостана, а Салават Юлаев — национальный герой башкирского народа."],"figure":{"src":"assets/golden-fleece/2026/10.webp","alt":"Памятник всаднику с поднятой рукой на каменном постаменте","width":429,"height":295}},{"title":"Янтарная столица","question":"Этот город называют янтарной столицей мира, так как в его окрестностях сосредоточено около 90 % мировых запасов янтаря.","choices":["Санкт-Петербург","Петропавловск-Камчатский","Калининград","Южно-Сахалинск"],"answer":2,"steps":["Крупное месторождение янтаря находится на берегу Балтийского моря рядом с посёлком Янтарным. В посёлке добывают и обрабатывают этот камень.","Янтарный находится в Калининградской области. Её главный город Калининград получил прозвище янтарной столицы."]},{"title":"Обелиск в столице","question":"В столице этой республики установлен обелиск «Центр Азии».","choices":["Алтай","Бурятия","Калмыкия","Тыва"],"answer":3,"steps":["Обелиск «Центр Азии» с земным шаром и высоким шпилем стоит на набережной Енисея в Кызыле.","В вариантах перечислены республики. Кызыл — столица Тывы, поэтому выбираем Тыву."],"figure":{"src":"assets/golden-fleece/2026/12.webp","alt":"Шпиль над земным шаром на каменном постаменте","width":290,"height":370}},{"title":"Автомобильный завод","question":"В этом городе находится крупнейший в России автомобильный завод.","choices":["Калининград","Набережные Челны","Москва","Тольятти"],"answer":3,"steps":["По масштабу производства легковых автомобилей подходит АвтоВАЗ. На нём производят автомобили марки «Лада».","Главная площадка АвтоВАЗа находится в Тольятти. В Набережных Челнах расположен другой крупный завод, КамАЗ, который известен своими грузовиками."]},{"title":"Древний храм","question":"Старейший из сохранившихся в России христианских храмов, заложенных после Крещения Руси, находится в городе ....","choices":["Нижнем Новгороде","Москве","Архангельске","Великом Новгороде"],"answer":3,"steps":["На фотографии Софийский собор, заложенный в 1045 году. Его построили в XI веке, вскоре после Крещения Руси в 988 году.","Собор стоит внутри кремля Великого Новгорода. Из двух городов со словом «Новгород» в названии подходит именно Великий Новгород."],"figure":{"src":"assets/golden-fleece/2026/14.webp","alt":"Белый храм с золотым и серебристыми куполами","width":411,"height":296}},{"title":"Город на вечной мерзлоте","question":"Самый большой на планете город, расположенный в зоне вечной мерзлоты, — столица Республики ....","choices":["Карелии","Тыва","Саха (Якутия)","Алтай"],"answer":2,"steps":["В зоне вечной мерзлоты грунт на глубине остаётся замёрзшим круглый год. Крупнейший город в такой зоне — Якутск, расположенный на реке Лене.","Якутск — столица Республики Саха. Второе название республики — Якутия. В списке оба названия стоят рядом."]},{"title":"Кремль для митрополита","question":"В этом городе, столице средневекового русского княжества, кремль был построен для резиденции митрополита.","choices":["Великий Новгород","Ростов Великий","Казань","Москва"],"answer":1,"steps":["Главная подсказка — назначение кремля. За его стенами устроили архиерейский двор, где жил и работал митрополит Иона Сысоевич.","Этот двор построили во второй половине XVII века. Сегодня его называют Ростовским кремлём, и находится он в Ростове Великом."],"figure":{"src":"assets/golden-fleece/2026/16.webp","alt":"Кремль с белыми стенами, башнями и куполами","width":421,"height":301}},{"title":"День вулкана","question":"В этом городе ежегодно проводится праздник «День вулкана».","choices":["Горно-Алтайск","Кызыл","Петропавловск-Камчатский","Улан-Удэ"],"answer":2,"steps":["Ищем праздник, связанный с Камчаткой и её действующими вулканами. В его программу традиционно входит восхождение на Авачинский вулкан.","Авачинский вулкан находится рядом с Петропавловском-Камчатским. В этом городе проводят события «Дня вулкана», например выставки и экскурсии."]},{"title":"Фигура на шпиле вокзала","question":"Фигура этого мифического существа, древнего символа столицы Татарстана, венчает шпиль Казанского вокзала в Москве.","choices":["Жар-птица","Грифон","Сфинкс","Крылатый змей"],"answer":3,"steps":["Столица Татарстана — Казань. На её гербе изображён Зилант, персонаж старинных легенд об основании города.","На шпиле Казанского вокзала изображён тот же Зилант. У него змеиные черты и крылья, поэтому подходит вариант «Крылатый змей»."],"figure":{"src":"assets/golden-fleece/2026/18.webp","alt":"Золотая фигура с крыльями и длинной шеей на шпиле","width":361,"height":298}},{"title":"Мост через Енисей","question":"В этом городе был построен первый мост через реку Енисей, завоевавший Гран-при и золотую медаль «За архитектурное совершенство и великолепное техническое исполнение» на Всемирной выставке в Париже.","choices":["Хабаровск","Красноярск","Абакан","Кызыл"],"answer":1,"steps":["Речь о первом железнодорожном мосте через Енисей, открытом в 1899 году. В 1900 году на выставке в Париже наградили его модель.","Мост по проекту Лавра Проскурякова построили в Красноярске. На фотографии видны более поздние железнодорожные пролёты этой переправы."],"figure":{"src":"assets/golden-fleece/2026/19.webp","alt":"Металлический мост с решётчатыми пролётами над широкой рекой","width":463,"height":286}},{"title":"Имя Русского музея","question":"Государственный Русский музей с момента открытия до 1917 года носил имя императора ....","choices":["Петра I","Николая I","Александра II","Александра III"],"answer":3,"steps":["Русский музей открылся в Михайловском дворце в 1898 году. Николай II учредил музей в память о своём отце.","Отцом Николая II был Александр III. При открытии музей назывался «Русский музей императора Александра III»."],"figure":{"src":"assets/golden-fleece/2026/20.webp","alt":"Светло-жёлтый дворец с колоннами и площадкой перед фасадом","width":455,"height":250}},{"title":"Настольная игра в Элисте","question":"Столицей этой настольной игры считается Элиста.","choices":["Шахматы","Шашки","Нарды","Домино"],"answer":0,"steps":["В Элисте есть комплекс Сити-Чесс, построенный к международным соревнованиям 1998 года.","В этом комплексе прошла 33-я Всемирная шахматная олимпиада. Поэтому Элисту называют столицей шахмат."]},{"title":"Здание в форме трактора","question":"Здание этого культурного учреждения, расположенного в южной столице России, по своей форме напоминает трактор.","choices":["Библиотека","Театр","Кинотеатр","Музей"],"answer":1,"steps":["Южной столицей называют Ростов-на-Дону. На его Театральной площади есть здание, в силуэте которого видны высокая «кабина» и длинные «гусеницы».","Это здание Ростовского академического театра драмы имени Максима Горького. Значит, из четырёх типов учреждений подходит театр."],"figure":{"src":"assets/golden-fleece/2026/22.webp","alt":"Здание с длинным низким фасадом и высоким выступом","width":455,"height":329}},{"title":"Полумарафон","question":"В этом городе ежегодно проводится легкоатлетический полумарафон «Оружейная столица».","choices":["Екатеринбург","Ижевск","Челябинск","Тула"],"answer":3,"steps":["Ижевск и Тула известны производством оружия. Чтобы выбрать город, проверим маршрут соревнования на сайте организаторов.","Полумарафон входит в серию «Тульский марафон». Его трасса проложена по Туле, поэтому выбираем этот город."]},{"title":"Башни Академгородка","question":"Наклонные башни, построенные в Академгородке научной столицы России, получили народное название ....","choices":["«Гуси»","«Утки»","«Голуби»","«Соколы»"],"answer":0,"steps":["На снимке башни наклонены друг к другу и соединены переходом наверху. Вместе они напоминают двух птиц, которые соприкасаются клювами.","Эти башни находятся в Академпарке Новосибирска. На городском туристическом портале их называют «Гуси»."],"figure":{"src":"assets/golden-fleece/2026/24.webp","alt":"Две наклонные башни с оранжевыми полосами и переходом наверху","width":455,"height":296}},{"title":"Памятник в стихотворении","question":"В стихотворении «Памятник» А. С. Пушкин дал неофициальное название этому архитектурному шедевру, расположенному на Дворцовой площади.","choices":["Александровская колонна","Зимний дворец","Здание Главного штаба","Медный всадник"],"answer":0,"steps":["У Пушкина в стихотворении упомянут «Александрийский столп». Слово «столп» означает высокий столб или колонну.","В центре Дворцовой площади стоит Александровская колонна, воздвигнутая в честь Александра I. С ней часто связывают пушкинский образ."]},{"title":"Оренбургские платки","question":"Из пуха этих животных изготавливают ажурные аксессуары, благодаря которым город Оренбург получил неофициальный статус столицы пуховых платков.","choices":["Коза","Овца","Як","Верблюд"],"answer":0,"steps":["Для тонких ажурных платков нужна лёгкая и тёплая пряжа. Оренбургские мастерицы делают её из мягкого подшёрстка местной породы животных.","Этот пух вычёсывают у оренбургских коз. Поэтому в списке выбираем «Коза»."]},{"title":"Олимпийская столица","question":"Этот город в XX веке стал олимпийской столицей.","choices":["Казань","Москва","Сочи","Ленинград"],"answer":1,"steps":["XX век — годы с 1901 по 2000. Зимняя Олимпиада в Сочи состоялась в 2014 году, уже в XXI веке.","В 1980 году летние Олимпийские игры принимала Москва. Дата подходит под условие, значит, выбираем Москву."]},{"title":"Гимн Москвы","question":"Официальным гимном Москвы с 1995 года является песня ....","choices":["«Я шагаю по Москве»","«Москва! Звонят колокола…»","«Дорогая моя столица»","«Дорогие мои москвичи»"],"answer":2,"steps":["В законе от 14 июля 1995 года сказано, что гимн написан на основе песни «Моя Москва». Музыку написал Исаак Дунаевский, а слова — Марк Лисянский и Сергей Агранян.","В припеве этой песни звучит строка «Дорогая моя столица». Именно под таким названием песня дана в вариантах ответа."]},{"title":"Интерактивный музей","question":"Интерактивный музей в Санкт-Петербурге, в котором представлены собирательные образы нашей страны, называется ....","choices":["Российский этнографический музей","Гранд Макет Россия","Государственный Эрмитаж","Государственный Русский музей"],"answer":1,"steps":["На фотографии видны миниатюрные дома, дороги и железнодорожные пути. Вместе такие сцены показывают, как выглядят разные города и регионы России.","В Санкт-Петербурге эту экспозицию площадью 800 квадратных метров можно увидеть в музее «Гранд Макет Россия»."],"figure":{"src":"assets/golden-fleece/2026/29.webp","alt":"Посетители рассматривают миниатюрные дома и железную дорогу","width":369,"height":287}},{"title":"Два одинаковых проекта","question":"Эти сооружения, открытые в 1851 году, построены по идентичным проектам.","choices":["«Сталинские высотки» в Москве","Здания Сената и Синода в Санкт-Петербурге","Мосты Ломоносова и Старо-Калинкин в Санкт-Петербурге","Николаевские вокзалы в Санкт-Петербурге и Москве"],"answer":3,"steps":["В 1851 году открылось движение по всей железной дороге между Москвой и Санкт-Петербургом. Вокзалы в обоих городах построили по одному проекту Константина Тона и Рудольфа Желязевича.","Вокзалы назывались Николаевскими. Сегодня этот вокзал в Москве называется Ленинградским, а в Санкт-Петербурге — Московским."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
